WITH u AS (SELECT 'exp_togvarsel_lr_am5_f15_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am5_f15_A` UNION ALL SELECT 'exp_togvarsel_lr_am5_f15_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am5_f15_B` UNION ALL SELECT 'exp_togvarsel_bt_am5_f15_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am5_f15_A` UNION ALL SELECT 'exp_togvarsel_bt_am5_f15_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am5_f15_B` UNION ALL SELECT 'exp_togvarsel_lr_am5_f15cat_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am5_f15cat_A` UNION ALL SELECT 'exp_togvarsel_lr_am5_f15cat_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am5_f15cat_B` UNION ALL SELECT 'exp_togvarsel_bt_am5_f15cat_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am5_f15cat_A` UNION ALL SELECT 'exp_togvarsel_bt_am5_f15cat_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am5_f15cat_B` UNION ALL SELECT 'exp_togvarsel_lr_am10_f15_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am10_f15_A` UNION ALL SELECT 'exp_togvarsel_lr_am10_f15_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am10_f15_B` UNION ALL SELECT 'exp_togvarsel_bt_am10_f15_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am10_f15_A` UNION ALL SELECT 'exp_togvarsel_bt_am10_f15_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am10_f15_B` UNION ALL SELECT 'exp_togvarsel_lr_am10_f15cat_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am10_f15cat_A` UNION ALL SELECT 'exp_togvarsel_lr_am10_f15cat_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_am10_f15cat_B` UNION ALL SELECT 'exp_togvarsel_bt_am10_f15cat_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am10_f15cat_A` UNION ALL SELECT 'exp_togvarsel_bt_am10_f15cat_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_am10_f15cat_B` UNION ALL SELECT 'exp_togvarsel_lr_pm5_pm1400_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_pm5_pm1400_A` UNION ALL SELECT 'exp_togvarsel_lr_pm5_pm1400_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_pm5_pm1400_B` UNION ALL SELECT 'exp_togvarsel_bt_pm5_pm1400_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_pm5_pm1400_A` UNION ALL SELECT 'exp_togvarsel_bt_pm5_pm1400_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_pm5_pm1400_B` UNION ALL SELECT 'exp_togvarsel_lr_pm5_pm1400cat_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_pm5_pm1400cat_A` UNION ALL SELECT 'exp_togvarsel_lr_pm5_pm1400cat_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_lr_pm5_pm1400cat_B` UNION ALL SELECT 'exp_togvarsel_bt_pm5_pm1400cat_A' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_pm5_pm1400cat_A` UNION ALL SELECT 'exp_togvarsel_bt_pm5_pm1400cat_B' m, d, label, p FROM `ent-kixavvik-dev.disruptions.pred_exp_togvarsel_bt_pm5_pm1400cat_B`),
r AS (SELECT *, RANK() OVER (PARTITION BY m ORDER BY p) rk FROM u),
a AS (SELECT m, COUNT(*) n, COUNTIF(label) n_pos,
  ROUND(SAFE_DIVIDE(SUM(IF(label, rk, 0)) - COUNTIF(label)*(COUNTIF(label)+1)/2, COUNTIF(label)*COUNTIF(NOT label)),3) auc,
  ROUND(AVG(POW(p - CAST(label AS INT64), 2)),4) brier,
  ROUND(AVG(IF(p < 0.10, CAST(label AS INT64), NULL)),3) bad_green, ROUND(AVG(IF(p >= 0.30, CAST(label AS INT64), NULL)),3) bad_red,
  ROUND(COUNTIF(p < 0.10)/COUNT(*),2) share_green, ROUND(COUNTIF(p >= 0.30)/COUNT(*),2) share_red
  FROM r GROUP BY m)
SELECT REGEXP_EXTRACT(m, r'exp_togvarsel_(lr|bt)_') kind, REGEXP_EXTRACT(m, r'exp_togvarsel_(?:lr|bt)_(.*)_[AB]$') cfg, RIGHT(m,1) fold, n, n_pos, auc, brier, share_green, bad_green, share_red, bad_red
FROM a ORDER BY cfg, fold, kind
